
fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let max_len:usize=args.get(3).map(|x|x.parse().unwrap()).unwrap_or(10000);let mut stack=Vec::new();let mut spans=Vec::new();let mut prefix_mr=vec![0usize;ops.len()+1];let mut prefix_arith=vec![0usize;ops.len()+1];for(i,o)in ops.iter().enumerate(){prefix_mr[i+1]=prefix_mr[i]+usize::from(matches!(o.kind,OperationType::R|OperationType::Hmr));prefix_arith[i+1]=prefix_arith[i]+usize::from(matches!(o.kind,OperationType::X|OperationType::CX|OperationType::CCX|OperationType::Swap));if o.kind==OperationType::PushCondition{stack.push(i);}else if o.kind==OperationType::PopCondition{let start=stack.pop().unwrap();if i-start+1<=max_len&&prefix_mr[i+1]>prefix_mr[start]&&prefix_arith[i+1]>prefix_arith[start]{spans.push((start,i));}}}assert!(stack.is_empty());let mut log=File::create(format!("{}.jsonl",args[2])).unwrap();let mut positive=Vec::new();let timer=std::time::Instant::now();let mut counts=std::collections::BTreeMap::new();for(index,(start,end))in spans.iter().enumerate(){let r=reset_projection_certificate(&ops[*start..=*end],200000,100);*counts.entry(r.status).or_insert(0usize)+=1;let record=serde_json::json!({"start":start,"end":end,"proved_reset_projection":r.proved,"status":r.status,"operation_count":r.ops,"quantum_wires":r.quantum_wires,"classical_wires":r.classical_wires,"mr_events":r.mr,"input_coefficient_nodes":r.nodes,"outer_rng_caps":r.caps,"unresolved_quantum_wires":r.unresolved,"seconds":r.seconds});writeln!(log,"{record}").unwrap();if r.proved{positive.push((*start,*end));}if index%100==0{log.flush().unwrap();eprintln!("RESET_PROJECTION_PROGRESS candidates={index}/{} positive={} seconds={:.1}",spans.len(),positive.len(),timer.elapsed().as_secs_f64());}}positive.sort_unstable_by_key(|(s,e)|(*s,std::cmp::Reverse(*e)));let mut selected=Vec::new();for(s,e)in positive{if selected.last().map_or(true,|(_,last)|s>*last){selected.push((s,e));}}let mut skip=File::create(format!("{}.skip-u32le.bin",args[2])).unwrap();let mut removed=0usize;for(start,end)in &selected{for i in *start..=*end{if matches!(ops[i].kind,OperationType::X|OperationType::CX|OperationType::CCX|OperationType::Swap){skip.write_all(&u32::try_from(i).unwrap().to_le_bytes()).unwrap();removed+=1;}}}let report=serde_json::json!({"source_stream":args[1],"full_operation_count":ops.len(),"max_region_operations":max_len,"regions_tested":spans.len(),"status_counts":counts,"selected_disjoint_certified_regions":selected,"removed_quantum_value_operations":removed,"preserved_all_original_mr_classical_and_snapshots":true,"seconds":timer.elapsed().as_secs_f64(),"status":"UNIVERSAL_LOCAL_VALUE_REWRITE_CERTIFICATES_NOT_GLOBAL_RNG_CERTIFICATE"});std::fs::write(format!("{}.summary.json",args[2]),format!("{report}\n")).unwrap();println!("{report}");}
